from agent_databench.loop import run_episode
class BadTool:
    name = 'bad'
    def __init__(self):
        self.step = 0
    def chat(self, messages, tools):
        self.step += 1
        if self.step == 1:
            return {'content': '', 'tool_calls': [{'id': 'b1', 'name': 'no_such_tool', 'arguments': {}}]}
        return {'content': '', 'tool_calls': [{'id': 'b2', 'name': 'submit_answer', 'arguments': {'answer': '42'}}]}
ep = run_episode({'id': 'x', 'question': 'q'}, BadTool(), {'system_prompt': 'x', 'max_turns': 3})
